  "implementation": "def solve(case):
    import copy
    # Validate required fields
    required = ['word_token_indices', 'word_scores', 'forced_words', 'token_budget']
    for key in required:
        if key not in case:
            raise ValueError(f'Missing required field: {key}')
    wti = case['word_token_indices']
    ws = case['word_scores']
    forced = case['forced_words']
    budget = case['token_budget']
    if len(wti) != len(ws):
        raise ValueError('Mismatched lengths')
    # Infeasibility check
    forced_tokens = sum(len(wti[i]) for i in forced)
    if forced_tokens > budget:
        return {'retained_token_indices': [], 'selected_words': [], 'tokens_used': 0}
    # Build candidates for non-forced words
    forced_set = set(forced)
    candidates = []
    for i in range(len(wti)):
        if i not in forced_set:
            candidates.append((i, ws[i], len(wti[i])))
    # Sort: descending score, then ascending index
    candidates.sort(key=lambda x: (-x[1], x[0]))
    selected = set(forced)
    remaining = budget - forced_tokens
    for idx, score, token_cnt in candidates:
        if token_cnt <= remaining:
            selected.add(idx)
            remaining -= token_cnt
    # Build output in original order
    selected_sorted = sorted(selected)
    retained_tokens = []
    for idx in selected_sorted:
        retained_tokens.extend(wti[idx])
    tokens_used = sum(len(wti[i]) for i in selected_sorted)
    return {
        'retained_token_indices': retained_tokens,
        'selected_words': selected_sorted,
        'tokens_used': tokens_used
    }"
